  "/sw.js": "const VERSION = \"cac563b7cae7\";\nconst CACHE = \"navvied-shell-\" + VERSION;\nconst SHELL = [\"/\", \"/index.html\", \"/main.js\", \"/styles.css\", \"/boot.js\", \"/icon.svg\", \"/icon-tile.svg\", \"/icon-maskable.svg\", \"/icon-192.png\", \"/icon-512.png\", \"/icon-maskable-512.png\", \"/apple-touch-icon.png\", \"/manifest.webmanifest\"];\n\nself.addEventListener(\"install\", (event) => {\n  // `reload` goes to the network, so an old copy held by the browser is never stored as the new version.\n  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(SHELL.map((path) => new Request(path, { cache: \"reload\" })))).then(() => self.skipWaiting()));\n});\n\nself.addEventListener(\"activate\", (event) => {\n  event.waitUntil(\n    caches.keys()\n      .then((keys) => Promise.all(keys.filter((k) => k.startsWith(\"navvied-shell-\") && k !== CACHE).map((k) => caches.delete(k))))\n      .then(() => self.clients.claim()),\n  );\n});\n\nfunction cacheable(url) {\n  return url.origin === self.location.origin && !url.pathname.startsWith(\"/api/\") && url.pathname !== \"/ws\" && url.pathname !== \"/sw.js\" && SHELL.includes(url.pathname);\n}\n\nself.addEventListener(\"fetch\", (event) => {\n  const request = event.request;\n  if (request.method !== \"GET\") return;\n  const url = new URL(request.url);\n  if (url.origin !== self.location.origin) return;\n\n  if (request.mode === \"navigate\") {\n    event.respondWith(fetch(request).catch(() => caches.match(\"/index.html\")));\n    return;\n  }\n  if (!cacheable(url)) return;\n  // The files have fixed names, so the network comes first and the stored copy is only for when it is not there.\n  event.respondWith(\n    fetch(request, { cache: \"no-cache\" }).then((res) => {\n      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((cache) => cache.put(url.pathname, copy)); }\n      return res;\n    }).catch(() => caches.open(CACHE).then((cache) => cache.match(url.pathname)).then((hit) => hit || Response.error())),\n  );\n});\n",
